1	import type { Element } from "hast";
2	import "katex/dist/katex.min.css";
3	import type { Components } from "react-markdown";
4	import ReactMarkdown from "react-markdown";
5	import rehypeKatex from "rehype-katex";
6	import rehypeRaw from "rehype-raw";
7	import rehypeSanitize from "rehype-sanitize";
8	import remarkBreaks from "remark-breaks";
9	import remarkGfm from "remark-gfm";
10	import remarkMath from "remark-math";
11	import { isMentionElement, isTagElement, isTaskListItemElement } from "@/types/markdown";
12	import { rehypeHeadingId } from "@/utils/rehype-plugins/rehype-heading-id";
13	import { remarkDisableSetext } from "@/utils/remark-plugins/remark-disable-setext";
14	import { remarkMention } from "@/utils/remark-plugins/remark-mention";
15	import { remarkPreserveType } from "@/utils/remark-plugins/remark-preserve-type";
16	import { remarkSplitMixedTaskLists } from "@/utils/remark-plugins/remark-split-mixed-task-lists";
17	import { remarkTag } from "@/utils/remark-plugins/remark-tag";
18	import { CodeBlock } from "./CodeBlock";
19	import { SANITIZE_SCHEMA } from "./constants";
20	import { MarkdownRenderContext, rootMarkdownRenderContext } from "./MarkdownRenderContext";
21	import { Mention } from "./Mention";
22	import { AnchorLink, Blockquote, Heading, HorizontalRule, Image, InlineCode, Link, List, ListItem, Paragraph } from "./markdown";
23	import { Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from "./Table";
24	import { Tag } from "./Tag";
25	import { TaskListItem } from "./TaskListItem";
26	import { TrustedIframe } from "./TrustedIframe";
27	
28	interface MemoMarkdownRendererProps {
29	  content: string;
30	  resolvedMentionUsernames: Set<string>;
31	  /** Resource name of the memo (e.g. `memos/abc123`), used to target footnote links at the detail page. */
32	  memoName?: string;
33	  /** Whether the memo is rendered as a collapsed feed card. */
34	  compact?: boolean;
35	}
36	
37	function getMentionUsername(node: Element, children?: React.ReactNode): string {
38	  const dataMention = node.properties?.["data-mention"];
39	  if (typeof dataMention === "string" && dataMention !== "") {
40	    return dataMention;
41	  }
42	
43	  const camelDataMention = (node.properties as Record<string, unknown> | undefined)?.dataMention;
44	  if (typeof camelDataMention === "string" && camelDataMention !== "") {
45	    return camelDataMention;
46	  }
47	
48	  const text = Array.isArray(children) ? children.join("") : children;
49	  if (typeof text === "string" && text.startsWith("@")) {
50	    return text.slice(1).toLowerCase();
51	  }
52	
53	  return "";
54	}
55	
56	export const MemoMarkdownRenderer = ({ content, resolvedMentionUsernames, memoName, compact }: MemoMarkdownRendererProps) => {
57	  const markdownComponents: Components = {
58	    input: ({ node, ...inputProps }) => {
59	      if (node && isTaskListItemElement(node)) {
60	        return <TaskListItem {...inputProps} node={node} />;
61	      }
62	      return <input {...inputProps} />;
63	    },
64	    span: ({ node, ...spanProps }) => {
65	      if (node && isMentionElement(node)) {
66	        const username = getMentionUsername(node, spanProps.children);
67	        return <Mention {...spanProps} node={node} data-mention={username} resolved={resolvedMentionUsernames.has(username)} />;
68	      }
69	      if (node && isTagElement(node)) {
70	        return <Tag {...spanProps} node={node} />;
71	      }
72	      return <span {...spanProps} />;
73	    },
74	    h1: ({ children, ...props }) => (
75	      <Heading level={1} {...props}>
76	        {children}
77	      </Heading>
78	    ),
79	    h2: ({ children, ...props }) => (
80	      <Heading level={2} {...props}>
81	        {children}
82	      </Heading>
83	    ),
84	    h3: ({ children, ...props }) => (
85	      <Heading level={3} {...props}>
86	        {children}
87	      </Heading>
88	    ),
89	    h4: ({ children, ...props }) => (
90	      <Heading level={4} {...props}>
91	        {children}
92	      </Heading>
93	    ),
94	    h5: ({ children, ...props }) => (
95	      <Heading level={5} {...props}>
96	        {children}
97	      </Heading>
98	    ),
99	    h6: ({ children, ...props }) => (
100	      <Heading level={6} {...props}>
101	        {children}
102	      </Heading>
103	    ),
104	    p: ({ children, ...props }) => <Paragraph {...props}>{children}</Paragraph>,
105	    blockquote: ({ children, ...props }) => <Blockquote {...props}>{children}</Blockquote>,
106	    hr: (props) => <HorizontalRule {...props} />,
107	    ul: ({ children, ...props }) => <List {...props}>{children}</List>,
108	    ol: ({ children, ...props }) => (
109	      <List ordered {...props}>
110	        {children}
111	      </List>
112	    ),
113	    li: ({ children, ...props }) => <ListItem {...props}>{children}</ListItem>,
114	    a: ({ children, href, ...props }) => {
115	      // In-page anchors (footnote refs/backrefs, heading links) navigate within the memo rather
116	      // than opening a new tab; everything else is treated as an external link.
117	      if (typeof href === "string" && href.startsWith("#")) {
118	        return (
119	          <AnchorLink href={href} memoName={memoName} compact={compact} {...props}>
120	            {children}
121	          </AnchorLink>
122	        );
123	      }
124	      return (
125	        <Link href={href} {...props}>
126	          {children}
127	        </Link>
128	      );
129	    },
130	    code: ({ children, ...props }) => <InlineCode {...props}>{children}</InlineCode>,
131	    iframe: TrustedIframe,
132	    img: (props) => <Image {...props} />,
133	    pre: CodeBlock,
134	    table: ({ children, ...props }) => <Table {...props}>{children}</Table>,
135	    thead: ({ children, ...props }) => <TableHead {...props}>{children}</TableHead>,
136	    tbody: ({ children, ...props }) => <TableBody {...props}>{children}</TableBody>,
137	    tr: ({ children, ...props }) => <TableRow {...props}>{children}</TableRow>,
138	    th: ({ children, ...props }) => <TableHeaderCell {...props}>{children}</TableHeaderCell>,
139	    td: ({ children, ...props }) => <TableCell {...props}>{children}</TableCell>,
140	  };
141	
142	  return (
143	    <MarkdownRenderContext.Provider value={rootMarkdownRenderContext}>
144	      <ReactMarkdown
145	        remarkPlugins={[
146	          remarkDisableSetext,
147	          remarkMath,
148	          remarkGfm,
149	          remarkSplitMixedTaskLists,
150	          remarkBreaks,
151	          remarkMention,
152	          remarkTag,
153	          remarkPreserveType,
154	        ]}
155	        rehypePlugins={[
156	          rehypeRaw,
157	          [rehypeSanitize, SANITIZE_SCHEMA],
158	          rehypeHeadingId,
159	          [rehypeKatex, { throwOnError: false, strict: false }],
160	        ]}
161	        components={markdownComponents}
162	      >
163	        {content}
164	      </ReactMarkdown>
165	    </MarkdownRenderContext.Provider>
166	  );
167	};
